def generate(today, days, past_days):
    rng = random.Random(20261103)
    movies = [dict(id=f'SEED-M{i:03}', title=title, duration=90 + i % 12 * 5,
                   genre=genre, status='NOW_SHOWING' if i <= 32 else
                   'COMING_SOON' if i <= 44 else 'ENDED')
              for i, (title, genre) in enumerate(CATALOG, 1)]
    room_names = ['Hoa Sen', 'Sao Mai', 'Ngân Hà', 'Đại Dương',
                  'Hoàng Hôn', 'Bình Minh', 'Thiên Hà', 'Ánh Trăng']
    rooms = [dict(id=f'SEED-R{i:02}', name=f'Phòng {i:02} · {name}',
                  rowCount=10, seatsPerRow=10)
             for i, name in enumerate(room_names, 1)]
    seats = [dict(id=f'{room["id"]}-{row}{n:02}', roomId=room['id'], rowLabel=row,
                  seatNumber=n, type='COUPLE' if row == 'J' else
                  'VIP' if row in 'EFGH' else 'NORMAL',
                  status='MAINTENANCE' if (row, n) == ('A', 10) else
                  'DISABLED' if (row, n) == ('B', 10) else 'ACTIVE')
             for room in rooms for row in 'ABCDEFGHIJ' for n in range(1, 11)]
    surnames = ['Nguyễn', 'Trần', 'Lê', 'Phạm', 'Hoàng', 'Huỳnh',
                'Phan', 'Vũ', 'Đặng', 'Bùi', 'Đỗ', 'Hồ']
    names = ['Minh Anh', 'Thanh Bình', 'Ngọc Châu', 'Hải Đăng', 'Thu Hà',
             'Quang Huy', 'Bảo Linh', 'Tuấn Minh', 'Phương Thảo', 'Khánh Vy']
    customers, accounts = [], []
    for i in range(1, 121):
        kind = ['NORMAL', 'STUDENT', 'VIP'][(i - 1) % 3]
        customer = dict(id=f'SEED-C{i:03}',
                        fullName=f'{surnames[(i-1)//10]} {names[(i-1)%10]}',
                        phone=f'090{i:07}', email=f'demo{i:03}@example.test',
                        customerType=kind,
                        studentId=f'SEEDSV{i:06}' if kind == 'STUDENT' else None)
        customers.append(customer)
        accounts.append(dict(id=f'SEED-A{i:03}', email=None, passwordHash=DEMO_HASH,
                             role='CUSTOMER', customerId=customer['id']))
    accounts.append(dict(id='SEED-ADMIN', email='demo.admin@example.test',
                         passwordHash=DEMO_HASH, role='ADMIN', customerId=None))
    shows, tickets = [], []
    by_room = {r['id']: [s for s in seats if s['roomId'] == r['id']
                        and s['status'] == 'ACTIVE'] for r in rooms}
    for offset in range(-past_days, days + 1):
        day = today + timedelta(days=offset)
        pool = movies[:32] + (movies[44:] if offset < 0 else
                             movies[32:44] if offset >= 14 else [])
        for ri, room in enumerate(rooms):
            for slot, hour in enumerate([9, 12, 15, 18, 21]):
                movie = pool[(offset * 7 + ri * 5 + slot) % len(pool)]
                start = datetime.combine(day, datetime.min.time()).replace(hour=hour)
                show = dict(id=f'SEED-S{day:%Y%m%d}-{ri+1:02}-{slot+1}',
                            movieId=movie['id'], roomId=room['id'],
                            startTime=start.isoformat(),
                            endTime=(start + timedelta(minutes=movie['duration'])).isoformat(),
                            price=70000 + (20000 if day.weekday() >= 5 else 0)
                            + (20000 if hour >= 18 else 0) + ri % 3 * 10000)
                shows.append(show)
                for ti, seat in enumerate(rng.sample(by_room[room['id']], 2)):
                    customer = rng.choice(customers)
                    status = rng.choices(['SUCCESS', 'PENDING', 'FAILED', 'REFUNDED'],
                                         [80, 0, 15, 5] if offset < 0 else [35, 45, 15, 5])[0]
                    surcharge = dict(NORMAL=0, VIP=20000, COUPLE=50000)[seat['type']]
                    percent = dict(NORMAL=100, STUDENT=90, VIP=80)[customer['customerType']]
                    tickets.append(dict(id=f'{show["id"]}-T{ti+1}',
                                        customerId=customer['id'], showtimeId=show['id'],
                                        seatId=seat['id'],
                                        price=(show['price'] + surcharge) * percent // 100,
                                        paymentStatus=status))
    return dict(zip(['movies.json', 'cinemaRooms.json', 'seats.json', 'showtimes.json',
                     'customers.json', 'accounts.json', 'tickets.json'],
                    [movies, rooms, seats, shows, customers, accounts, tickets]))


def validate(data):
    indexes = {}
    for file, records in data.items():
        index = {r['id']: r for r in records}
        assert len(index) == len(records), f'Duplicate IDs: {file}'
        indexes[file] = index
    def linked(file, key):
        assert key in indexes[file], f'Missing reference: {file}: {key}'
        return indexes[file][key]
    schedules = defaultdict(list)
    for s in data['seats.json']:
        r = linked('cinemaRooms.json', s['roomId'])
        assert 1 <= s['seatNumber'] <= r['seatsPerRow']
    for s in data['showtimes.json']:
        m = linked('movies.json', s['movieId'])
        linked('cinemaRooms.json', s['roomId'])
        start, end = map(datetime.fromisoformat, [s['startTime'], s['endTime']])
        assert end - start == timedelta(minutes=m['duration'])
        assert s['price'] > 0
        schedules[s['roomId']].append((start, end))
    for times in schedules.values():
        times.sort()
        assert all(a[1] <= b[0] for a, b in zip(times, times[1:])), 'Overlapping shows'
    active = set()
    for t in data['tickets.json']:
        linked('customers.json', t['customerId'])
        s = linked('showtimes.json', t['showtimeId'])
        seat = linked('seats.json', t['seatId'])
        assert seat['roomId'] == s['roomId'] and t['price'] > 0
        if t['paymentStatus'] in ('PENDING', 'SUCCESS'):
            assert seat['status'] == 'ACTIVE'
            key = (t['showtimeId'], t['seatId'])
            assert key not in active, 'Double-booked seat'
            active.add(key)
    for a in data['accounts.json']:
        if a['role'] == 'CUSTOMER':
            linked('customers.json', a['customerId'])
    for key in ['email', 'phone', 'studentId']:
        values = [c[key].lower() for c in data['customers.json'] if c.get(key)]
        assert len(values) == len(set(values)), f'Duplicate customer {key}'


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--directory', type=Path, default=Path(__file__).resolve().parent)
    parser.add_argument('--days', type=int, default=30, help='Number of future days (default 30)')
    parser.add_argument('--past-days', type=int, default=7, help='Number of past days (default 7)')
    args = parser.parse_args()
    if not 1 <= args.days <= 365 or not 0 <= args.past_days <= 365:
        parser.error('days must be 1..365; past-days must be 0..365')
    root = args.directory.resolve()
    root.mkdir(parents=True, exist_ok=True)
    today = datetime.now(ZoneInfo('Asia/Ho_Chi_Minh')).date()
    merged, originals, additions = {}, {}, {}
    for file, records in generate(today, args.days, args.past_days).items():
        path = root / file
        original = path.read_bytes() if path.exists() else None
        originals[file] = original
        existing = json.loads(original) if original is not None else []
        if not isinstance(existing, list):
            raise ValueError(f'{file} must contain a JSON array')
        ids = {r['id'] for r in existing}
        extra = [r for r in records if r['id'] not in ids]
        merged[file] = existing + extra
        additions[file] = len(extra)
    validate(merged)
    backup = None
    if any(additions.values()):
        backup = Path(tempfile.mkdtemp(prefix='n6-seed-backup-'))
        for file, original in originals.items():
            if original is not None:
                (backup / file).write_bytes(original)
        for file, records in merged.items():
            if not additions[file]:
                continue
            path = root / file
            # Refuse to replace data changed by the running application during generation.
            assert (path.read_bytes() if path.exists() else None) == originals[file], \
                f'{file} changed while seeding; stop application writes and retry'
            with tempfile.NamedTemporaryFile(mode='w', encoding='utf-8', dir=root,
                                             prefix='.seed-', suffix='.tmp', delete=False) as tmp:
                json.dump(records, tmp, ensure_ascii=False, indent=2)
                tmp.write('\n')
            Path(tmp.name).replace(path)
    for file, records in merged.items():
        print(f'{file}: {len(records)} records (+{additions[file]})')
    if backup:
        print(f'Backup: {backup}')
    print(f'Schedules: {today - timedelta(days=args.past_days)} through '
          f'{today + timedelta(days=args.days)} (Asia/Ho_Chi_Minh)')
    print('Demo login: demo.admin@example.test / N6Demo!2026')
    print('Customer logins: demo001@example.test through demo120@example.test / N6Demo!2026')


if __name__ == '__main__':
    main()
